css:
:where(.wtyg-map-site_animal_tourism) *{margin: 0; padding: 0; box-sizing: border-box;}
:where(.wtyg-map-site_animal_tourism){background: #0a0a0a; overflow: hidden;}
:where(.wtyg-map-site_animal_tourism) :is([data-wtyg-id="atm-container"],#wtyg-noid-atm-container) *{box-sizing: border-box;}
:where(.wtyg-map-site_animal_tourism) :is([data-wtyg-id="atm-map"],#wtyg-noid-atm-map){width: 100%; height: 100%; position: relative; background: #2d3436; z-index: 1;}
:where(.wtyg-map-site_animal_tourism) .atm-overlay{position: absolute; top: 0; left: 0; right: 0; z-index: 1000; background: linear-gradient(180deg, rgba(45,52,54,0.95) 0%, rgba(45,52,54,0.7) 70%, transparent 100%); padding: 1.5rem 2rem 3rem; pointer-events: none;}
:where(.wtyg-map-site_animal_tourism) .atm-header{display: flex; justify-content: space-between; align-items: flex-start; gap: 1.5rem; flex-wrap: wrap;}
:where(.wtyg-map-site_animal_tourism) .atm-title h1{font-family: 'Cormorant Garamond', serif; font-size: clamp(1.5rem, 4vw, 3rem); font-weight: 300; letter-spacing: 0.02em; margin: 0 0 0.3rem 0; color: #f5f5f0; animation: atmFadeIn 0.8s ease;}
:where(.wtyg-map-site_animal_tourism) .atm-title p{font-family: 'Work Sans', sans-serif; font-size: clamp(0.7rem, 1.5vw, 0.95rem); color: #d4a574; letter-spacing: 0.05em; text-transform: uppercase; font-weight: 300; margin: 0; animation: atmFadeIn 0.8s ease 0.2s both;}
:where(.wtyg-map-site_animal_tourism) .atm-filters{pointer-events: auto; display: flex; gap: 0.5rem; flex-wrap: wrap; animation: atmFadeIn 0.8s ease 0.4s both;}
:where(.wtyg-map-site_animal_tourism) .atm-btn{background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.15); color: #f5f5f0; padding: 0.5rem 1rem; border-radius: 2rem; font-family: 'Work Sans', sans-serif; font-size: 0.8rem; cursor: pointer; transition: all 0.3s; backdrop-filter: blur(10px);}
:where(.wtyg-map-site_animal_tourism) .atm-btn:hover{background: rgba(255,255,255,0.15); border-color: #d4a574; transform: translateY(-2px);}
:where(.wtyg-map-site_animal_tourism) .atm-btn.active{background: #d4a574; border-color: #d4a574; color: #2d3436; font-weight: 500;}
:where(.wtyg-map-site_animal_tourism) .atm-stats{position: absolute; bottom: 1.5rem; left: 2rem; z-index: 1000; background: rgba(45,52,54,0.9); backdrop-filter: blur(20px); border: 1px solid rgba(255,255,255,0.1); border-radius: 1rem; padding: 1rem 1.5rem; animation: atmFadeIn 0.8s ease 0.6s both; pointer-events: none;}
:where(.wtyg-map-site_animal_tourism) .atm-stat{display: flex; align-items: baseline; gap: 0.5rem; margin-bottom: 0.3rem;}
:where(.wtyg-map-site_animal_tourism) .atm-stat:last-child{margin-bottom: 0;}
:where(.wtyg-map-site_animal_tourism) .atm-stat-num{font-family: 'Cormorant Garamond', serif; font-size: 1.8rem; font-weight: 600; color: #d4a574;}
:where(.wtyg-map-site_animal_tourism) .atm-stat-label{font-family: 'Work Sans', sans-serif; font-size: 0.75rem; color: #f5f5f0; opacity: 0.8; text-transform: uppercase; letter-spacing: 0.05em;}
@keyframes atmFadeIn{ from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 768px){:where(.wtyg-map-site_animal_tourism) :is([data-wtyg-id="atm-container"],#wtyg-noid-atm-container){height: 600px !important;}
:where(.wtyg-map-site_animal_tourism) .atm-overlay{padding: 1rem 1rem 2rem;}
:where(.wtyg-map-site_animal_tourism) .atm-header{flex-direction: column; gap: 1rem;}
:where(.wtyg-map-site_animal_tourism) .atm-stats{left: 1rem; bottom: 1rem; padding: 0.8rem 1.2rem;}}
:where(.wtyg-map-site_animal_tourism) .leaflet-popup-content-wrapper{background: rgba(45,52,54,0.98) !important; backdrop-filter: blur(20px); border: 1px solid rgba(255,255,255,0.15) !important; border-radius: 1rem !important; box-shadow: 0 20px 60px rgba(0,0,0,0.4) !important; padding: 0 !important;}
:where(.wtyg-map-site_animal_tourism) .leaflet-popup-content{margin: 0 !important; min-width: 260px; font-family: 'Work Sans', sans-serif;}
:where(.wtyg-map-site_animal_tourism) .atm-popup{padding: 1.2rem;}
:where(.wtyg-map-site_animal_tourism) .atm-popup-cat{display: inline-block; background: #d4a574; color: #2d3436; padding: 0.25rem 0.7rem; border-radius: 1rem; font-size: 0.65rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 0.8rem;}
:where(.wtyg-map-site_animal_tourism) .atm-popup-name{font-family: 'Cormorant Garamond', serif; font-size: 1.3rem; font-weight: 600; color: #f5f5f0; margin-bottom: 0.4rem; line-height: 1.3;}
:where(.wtyg-map-site_animal_tourism) .atm-popup-addr{color: #d4a574; font-size: 0.85rem; line-height: 1.5; margin-bottom: 0.3rem;}
:where(.wtyg-map-site_animal_tourism) .atm-popup-country{color: rgba(255,255,255,0.6); font-size: 0.8rem; font-weight: 300;}
:where(.wtyg-map-site_animal_tourism) .leaflet-popup-tip{background: rgba(45,52,54,0.98) !important; border: 1px solid rgba(255,255,255,0.15) !important;}
:where(.wtyg-map-site_animal_tourism) .leaflet-popup-close-button{color: #f5f5f0 !important; font-size: 1.3rem !important; opacity: 0.6 !important;}
:where(.wtyg-map-site_animal_tourism) .leaflet-popup-close-button:hover{opacity: 1 !important;}
